export interface ForgeTrait {
  id: string;
  name: string;
  description?: string;
  /** Effect text. Use [L] as a placeholder replaced by the current level (application count). */
  effect: string;
  schmiedepunktKosten: number;
  /** Maximum times this trait may be added. undefined or 1 = not scalable. */
  maxLevel: number;
  scalable: boolean;
  /** If true, all players can see this trait in their knowledge tab. */
  isPublic: boolean;
  /** What type of equipment this trait can be applied to. */
  appliesTo?: 'weapon' | 'armor' | 'all';
  libraryOrigin?: string;
  libraryOriginName?: string;
}

// ── In-session state ──────────────────────────────────────────────────────────

/** A single material entry within a slot, with its individual forge count. */
export interface SlotMaterialEntry {
  material: MaterialBlock;
  /** Number of times this material has been forged. Cost of the n-th forge = n SP. */
  forgeCount: number;
  /** Resource item id when taken from sheet.resources (enforced mode). */
  resourceItemId?: string;
}

export interface MaterialSlotState {
  /** Multiple materials can be placed in one slot (e.g. for special class abilities). */
  entries: SlotMaterialEntry[];
}

/** SP cost of the NEXT forge for an entry that has already been forged forgeCount times. */
export function nextForgeCost(forgeCount: number): number {
  return forgeCount + 1;
}

/** Total SP already spent forging an entry (sum 1+2+…+forgeCount). */
export function totalForgeSPSpent(forgeCount: number): number {
  return (forgeCount * (forgeCount + 1)) / 2;
}

export interface AppliedTraitState {
  trait: ForgeTrait;
  /** How many times this trait has been applied (capped by maxLevel). */
  level: number;
}

/** Computed preview of one stat set after forging. */
export interface ForgedStatPreview {
  haltbarkeit: number;
  effektivitaet: number;
  weight: number;
  ruestungsmalus?: number;
  extraEffect: string;
  /** Accumulated stat requirement contribution. */
  statRequirement: number;
}

// ── Forging history embedded in the produced ItemBlock ────────────────────────

export interface ForgedMaterialRecord {
  name: string;
  forgeCount: number;
}

export interface ForgedTraitRecord {
  name: string;
  level: number;
}

export interface ForgingData {
  createdAt: number;
  itemType: 'weapon' | 'armor';
  primaryMaterials?: ForgedMaterialRecord[];
  secondaryMaterials?: ForgedMaterialRecord[];
  bonusMaterials?: ForgedMaterialRecord[];
  appliedTraits: ForgedTraitRecord[];
  totalSP: number;
  spentSP: number;
}

// ── Helpers ───────────────────────────────────────────────────────────────────

export function createEmptyMaterialBlock(): MaterialBlock {
  return {
    id: `mat_${Date.now()}_${Math.random().toString(36).substring(2, 9)}`,
    name: 'Neues Material',
    description: '',
    isPublic: false,
    canBeWeaponMaterial: true,
    canBeArmorMaterial: false,
    cost: 0,
    rarity: 'COMMON',
    stackable: false,
    stackLevels: [],
    weaponStats: {
      haltbarkeit: 50,
      haltbarkeitSkalierung: 10,
      effektivitaet: 5,
      effektivitaetSkalierung: 2,
      extraEffect: '',
      weight: 1,
      reqBase: 0,
      reqScaling: 0,
    },
    armorStats: {
      haltbarkeit: 80,
      haltbarkeitSkalierung: 15,
      effektivitaet: 5,
      effektivitaetSkalierung: 2,
      extraEffect: '',
      weight: 2,
      ruestungsmalus: 0,
      reqBase: 0,
      reqScaling: 0,
    },
  };
}

export function createEmptyForgeTrait(): ForgeTrait {
  return {
    id: `trait_${Date.now()}_${Math.random().toString(36).substring(2, 9)}`,
    name: 'Neues Merkmal',
    description: '',
    effect: 'Effekt [L]',
    schmiedepunktKosten: 10,
    maxLevel: 1,
    scalable: false,
    isPublic: false,
    appliesTo: 'all',
  };
}

/** Replace [L] in an effect string with the given level number. */
export function formatTraitEffect(trait: ForgeTrait, level: number): string {
  if (trait.scalable) {
    return trait.effect.replace(/\[L\]/g, String(level));
  }
  return trait.effect;
}

/** Compute the forged stats of a material after n forges. Returns null if stats are missing. */
export function computeForgedStats(
  material: MaterialBlock,
  forgeCount: number,
  isWeapon: boolean
): ForgedStatPreview | null {
  const base = isWeapon ? material.weaponStats : material.armorStats;
  if (!base) return null;
  return {
    haltbarkeit: base.haltbarkeit + forgeCount * base.haltbarkeitSkalierung,
    effektivitaet: base.effektivitaet + forgeCount * base.effektivitaetSkalierung,
    weight: base.weight ?? 0,
    ruestungsmalus: base.ruestungsmalus,
    extraEffect: base.extraEffect ?? '',
    statRequirement: (base.reqBase ?? 0) + forgeCount * (base.reqScaling ?? 0),
  };
}
